<template><div class="auth-screen"><div class="auth-art"><div class="auth-brand"><span class="brand-mark">✦</span> tasknest</div><div class="art-copy"><div class="art-pill">✧ MAKE SPACE FOR YOUR GOALS</div><h1>Your next<br><em>chapter</em><br>starts here.</h1><p>Organize your ideas, build momentum, and celebrate every small win.</p><div class="art-orbit"><div class="orbit-card one">✦ &nbsp; Your workspace <span>Ready</span></div><div class="orbit-card two">◷ &nbsp; Daily progress <b>+1</b></div><div class="orbit-center">✧</div></div></div><div class="art-footer">A little more clarity, every day.</div></div><div class="auth-panel"><form class="auth-form" @submit.prevent="submit"><div class="eyebrow">GET STARTED</div><h2>Create your account</h2><p class="muted">Your organized life is one step away.</p><label>Your name<input v-model.trim="name" required maxlength="80" autocomplete="name" placeholder="Alex Morgan"></label><label>Email address<input v-model.trim="email" type="email" required autocomplete="email" placeholder="you@example.com"></label><label>Password<input v-model="password" type="password" required minlength="8" autocomplete="new-password" placeholder="At least 8 characters"></label><p v-if="error" class="form-error">{{error}}</p><button class="btn primary full" :disabled="busy">{{busy?'Creating…':'Create account →'}}</button><p class="auth-switch">Already have an account? <NuxtLink to="/login">Sign in</NuxtLink></p></form><div class="auth-foot">© 2026 TaskNest · Make room for meaningful work</div></div></div></template>
<script setup>
definePageMeta({layout:false});const auth=useAuthStore();const name=ref('');const email=ref('');const password=ref('');const error=ref('');const busy=ref(false);
async function submit(){busy.value=true;error.value='';try{await auth.register(name.value,email.value,password.value);await navigateTo('/')}catch(e){error.value=e.message}finally{busy.value=false}}
</script>
